const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const multiline=s=>esc(s).replaceAll('\n','<br>');
export const categoryLabel=s=>s.includes('配對')?'Match the connections':s.includes('聽音')?'Listen and choose':s.includes('情境')?'Complete the conversation':s.includes('填空')?'Choose what fits':s.includes('翻譯')?'Connect the meaning':s.includes('認字')?'Read and choose':'Choose the reading';
export function draftQuestionMarkup(q,t,{play,icon}){
 const outcome=t.outcomes[t.index],answerVisible=t.answered,canAnswer=!q.listening||t.heard||t.previewed;
 const sourceKey=q.kind==='matching'?q.pairs.map(p=>`${p.label} → ${p.answer}`).join('\n'):q.correct.map(id=>q.options.find(o=>o.id===id)?.label).join(' / ')||'No answer marked in the source.';
 let body=`<span class="status-chip">Team draft · ${q.bank==='starting'?'Starting check':'Worksheet preview'}</span><p class="eyebrow draft-category">${categoryLabel(q.category)}</p><h1 class="draft-prompt" lang="zh-Hant">${multiline(q.prompt)}</h1>`;
 if(q.listening){body+=`<div class="listening-card">${q.audioText?play({key:`assessment:${q.id}`,text:q.audioText,kind:'assessment'},'the listening prompt'):`<span class="status-chip">Exact recording pending</span>`}<p id="listening-hint" class="fine-print">${t.heard?'Audio started. Choose what you heard.':t.previewed?'Written cue preview · this item will not be scored.':q.audioText?'Play the prompt before choosing. A Taiwan Mandarin device voice is required.':'A written cue is available for team review.'}</p>${!t.answered&&!t.previewed?'<button class="text-btn" data-action="preview-listening">Preview written cue · unscored</button>':''}${t.previewed||t.answered?`<p class="source-cue">Source cue: <b>${esc(q.audioHint||'Not supplied')}</b></p>`:''}</div>`;}
 if(!q.scoreAllowed)body+='<p class="draft-notice">This item needs content review. Your response will not be scored.</p>';
 if(q.kind==='matching'){
  body+=`<div class="matching-list">${q.pairs.map(p=>`<label class="match-row"><span lang="zh-Hant">${esc(p.label)}</span><select data-match="${p.id}" aria-label="Match ${esc(p.label)}" ${answerVisible?'disabled':''}><option value="">Choose…</option>${q.matchChoices.map(v=>`<option value="${esc(v)}" ${t.matchAnswers[p.id]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>${answerVisible&&q.scoreAllowed?`<small>Worksheet key: ${esc(p.answer)}</small>`:''}</label>`).join('')}</div>${!answerVisible?'<button class="btn primary wide" data-action="check-matching">Check these matches</button>':''}`;
 }else{
  body+=`<div class="answers draft-answers">${q.options.map(o=>`<button class="answer ${answerVisible&&outcome?.graded&&q.correct.includes(o.id)?'correct':answerVisible&&outcome?.graded&&t.chosen===o.id?'incorrect':answerVisible&&t.chosen===o.id?'selected':''}" data-answer="${esc(o.id)}" ${answerVisible||!canAnswer?'disabled':''}><span>${o.id.toUpperCase()}</span><b lang="zh-Hant">${multiline(o.label)}</b>${answerVisible&&outcome?.graded&&q.correct.includes(o.id)?icon('check'):''}</button>`).join('')}</div>`;
 }
 if(answerVisible){body+=`<div class="feedback ${outcome?.graded&&!outcome.correct?'wrong':''}" role="status"><h2>${!outcome?.graded?'Preview saved · not scored':outcome.correct?'Matches the worksheet key.':'Different from the worksheet key.'}</h2><p>${outcome?.graded?'This is a draft worksheet result, pending content review.':'No score or learning unlock is changed.'}</p></div><details class="quiet-details"><summary>Source & review notes</summary><p>Team-authored practice text. This is not a COCT quotation.</p><p>Worksheet row ${q.source.row} · ${q.source.sourceReviewCheckbox?'A review checkbox is checked in the source; this import remains a draft.':'Imported without claiming content approval.'}</p>${q.flags.length?`<ul>${q.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}<p>Worksheet key:</p><p class="source-key">${multiline(sourceKey)}</p>${q.imageBrief?`<p>Image brief only: ${esc(q.imageBrief)}</p>`:''}${q.focus?`<p>Source focus: ${esc(q.focus)}</p>`:''}<a href="${esc(q.source.url)}" target="_blank" rel="noopener">Open source worksheet ↗</a><details><summary>Original wording and key</summary><p class="original-question" lang="zh-Hant">${multiline(q.rawText)}</p></details></details>`;
 }else body+='<button class="text-btn wide" data-action="show-draft-key">Show worksheet key · unscored</button>';
 return body;
}
